const DAYS=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
const recipes=[
 {name:'Moong Dal Chilla',diet:['vegetarian','vegan'],goals:['speedy','protein','low-calorie'],appliances:['stove'],time:20,cost:95,cal:320,protein:22,ingredients:{'Moong dal':'250 g','Onion':'2','Tomato':'2','Coriander':'1 bunch'}},
 {name:'Paneer Tikka Bowl',diet:['vegetarian'],goals:['protein','healthy-comfort'],appliances:['stove','air-fryer','oven'],time:30,cost:165,cal:510,protein:31,ingredients:{'Paneer':'300 g','Capsicum':'2','Curd':'200 g','Rice':'300 g'}},
 {name:'Rajma Rice Bowl',diet:['vegetarian','vegan'],goals:['protein','family','healthy-comfort'],appliances:['stove','pressure-cooker'],time:40,cost:120,cal:560,protein:24,ingredients:{'Rajma':'300 g','Rice':'400 g','Onion':'2','Tomato':'3'}},
 {name:'Soya Keema Wrap',diet:['vegetarian','vegan'],goals:['protein','speedy','fakeaway'],appliances:['stove'],time:25,cost:110,cal:430,protein:29,ingredients:{'Soya granules':'250 g','Whole wheat wraps':'6','Onion':'2','Capsicum':'1'}},
 {name:'Vegetable Pulao & Raita',diet:['vegetarian'],goals:['family','healthy-comfort'],appliances:['stove','pressure-cooker'],time:28,cost:130,cal:475,protein:14,ingredients:{'Rice':'400 g','Mixed vegetables':'500 g','Curd':'300 g'}},
 {name:'Chana Masala',diet:['vegetarian','vegan'],goals:['protein','gut-friendly'],appliances:['stove','pressure-cooker'],time:35,cost:105,cal:440,protein:21,ingredients:{'Chickpeas':'350 g','Tomato':'3','Onion':'2','Whole wheat atta':'500 g'}},
 {name:'Palak Tofu',diet:['vegetarian','vegan'],goals:['low-calorie','protein','gut-friendly'],appliances:['stove','blender'],time:32,cost:170,cal:390,protein:27,ingredients:{'Tofu':'300 g','Spinach':'500 g','Garlic':'1 bulb','Rice':'300 g'}},
 {name:'Masala Oats Khichdi',diet:['vegetarian','vegan'],goals:['speedy','low-calorie','gut-friendly'],appliances:['stove','pressure-cooker'],time:20,cost:85,cal:350,protein:15,ingredients:{'Oats':'300 g','Moong dal':'150 g','Mixed vegetables':'300 g'}}
];
const steps=[
 {title:'Which days will you cook?',sub:'Pick the days you want meals planned for.',type:'days'},
 {title:"What's your weekly budget?",sub:'Set what you’re happy to spend on those days.',type:'budget'},
 {title:'What are you in the mood for?',sub:'Pick up to 3 goals.',type:'goals'},
 {title:'Any dietary needs?',sub:'Pick all that apply.',type:'diet'},
 {title:'What appliances do you have?',sub:'Select everything we can plan with.',type:'appliances'},
 {title:'One last detail',sub:'Tell us what is already in your kitchen.',type:'pantry'}
];
const state=JSON.parse(localStorage.getItem('plateful-state')||'null')||{step:0,days:[...DAYS],budget:1800,people:2,goals:['protein'],diet:['vegetarian'],appliances:['stove','pressure-cooker'],pantry:''};
const $=id=>document.getElementById(id); const el=$('stepContent');
function save(){localStorage.setItem('plateful-state',JSON.stringify(state));$('savedStatus').textContent='Plan auto-saved'}
function option(label,value,group,emoji,selected){return `<button class="option ${selected?'selected':''}" data-group="${group}" data-value="${value}"><span class="emoji">${emoji}</span><span>${label}</span></button>`}
function render(){const s=steps[state.step];$('progressBar').style.width=`${((state.step+1)/steps.length)*100}%`;$('stepCount').textContent=`${state.step+1} / ${steps.length}`;$('backButton').style.visibility=state.step?'visible':'hidden';let body='';
 if(s.type==='days') body=`<div class="option-grid">${DAYS.map(d=>option(d,d,'days','',state.days.includes(d))).join('')}</div>`;
 if(s.type==='budget') body=`<div class="budget-value">₹<span id="budgetNumber">${state.budget}</span></div><div class="budget-caption">for ${state.days.length} cooking days</div><input class="range" id="budgetRange" type="range" min="500" max="5000" step="100" value="${state.budget}"><div class="range-labels"><span>₹500</span><span>₹5,000</span></div><div class="people-box"><div><strong>How many people?</strong><div class="budget-caption" style="text-align:left;margin:5px 0 0">We’ll scale every recipe.</div></div><div class="counter"><button id="minusPeople">−</button><strong id="peopleNumber">${state.people}</strong><button id="plusPeople">+</button></div></div>`;
 const goals=[['Speedy meals','speedy','⚡'],['Low calorie','low-calorie','⚖️'],['Family favourites','family','👨‍👩‍👧‍👦'],['Healthy comfort','healthy-comfort','🥗'],['Fakeaway','fakeaway','🥡'],['Gut friendly','gut-friendly','🌱'],['Protein packed','protein','💪']];
 if(s.type==='goals') body=`<div class="option-grid">${goals.map(x=>option(x[0],x[1],'goals',x[2],state.goals.includes(x[1]))).join('')}</div>`;
 const diets=[['No preference','none','◯'],['Vegetarian','vegetarian','🥕'],['Vegan','vegan','🌱'],['Egg-friendly','eggetarian','🥚']];
 if(s.type==='diet') body=`<div class="option-grid">${diets.map(x=>option(x[0],x[1],'diet',x[2],state.diet.includes(x[1]))).join('')}</div>`;
 const appliances=[['Gas / induction stove','stove','🔥'],['Pressure cooker','pressure-cooker','♨️'],['Air fryer','air-fryer','🍟'],['Oven','oven','▣'],['Microwave','microwave','〽️'],['Blender','blender','🥤']];
 if(s.type==='appliances') body=`<div class="option-grid">${appliances.map(x=>option(x[0],x[1],'appliances',x[2],state.appliances.includes(x[1]))).join('')}</div>`;
 if(s.type==='pantry') body=`<label for="pantry"><strong>Ingredients you already have</strong></label><textarea class="text-input" id="pantry" rows="6" placeholder="Rice, onion, tomato, paneer…">${state.pantry}</textarea><p style="margin-top:12px">We’ll prioritise meals that use these ingredients and reduce waste.</p>`;
 el.innerHTML=`<h1>${s.title}</h1><p>${s.sub}</p>${body}`; bind();$('continueButton').textContent=state.step===steps.length-1?'Generate my plan →':'Continue →';save();}
function bind(){document.querySelectorAll('.option').forEach(b=>b.onclick=()=>{const g=b.dataset.group,v=b.dataset.value;if(g==='goals'){state[g].includes(v)?state[g]=state[g].filter(x=>x!==v):state[g].length<3&&state[g].push(v)}else if(g==='diet'){state[g]=v==='none'?['none']:[v]}else{state[g].includes(v)?state[g]=state[g].filter(x=>x!==v):state[g].push(v)}render()});
 if($('budgetRange')) $('budgetRange').oninput=e=>{state.budget=+e.target.value;$('budgetNumber').textContent=state.budget;save()};
 if($('minusPeople')){$('minusPeople').onclick=()=>{state.people=Math.max(1,state.people-1);render()};$('plusPeople').onclick=()=>{state.people=Math.min(8,state.people+1);render()}}
 if($('pantry')) $('pantry').oninput=e=>{state.pantry=e.target.value;save()};}
function validate(){const t=steps[state.step].type;if(t==='days'&&!state.days.length)return 'Select at least one cooking day';if(t==='goals'&&!state.goals.length)return 'Choose at least one meal goal';if(t==='diet'&&!state.diet.length)return 'Choose a dietary preference';if(t==='appliances'&&!state.appliances.length)return 'Choose at least one appliance';return ''}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2200)}
function generate(){ $('wizard').classList.add('hidden');$('loadingScreen').classList.remove('hidden');setTimeout(()=>$('loadTwo').classList.add('done'),500);setTimeout(()=>$('loadThree').classList.add('done'),1000);setTimeout(showDashboard,1500)}
function chooseMeals(){let candidates=recipes.filter(r=>(state.diet.includes('none')||state.diet.some(d=>r.diet.includes(d)))&&r.appliances.some(a=>state.appliances.includes(a)));if(!candidates.length)candidates=[...recipes];candidates.sort((a,b)=>state.goals.filter(g=>b.goals.includes(g)).length-state.goals.filter(g=>a.goals.includes(g)).length||a.cost-b.cost);return state.days.map((day,i)=>({...candidates[i%candidates.length],day}))}
function showDashboard(){const meals=chooseMeals();$('loadingScreen').classList.add('hidden');$('dashboard').classList.remove('hidden');const cost=meals.reduce((s,m)=>s+m.cost*state.people/2,0);const protein=Math.round(meals.reduce((s,m)=>s+m.protein,0)/meals.length);const calories=Math.round(meals.reduce((s,m)=>s+m.cal,0)/meals.length);$('planSummary').textContent=`${meals.length} dinners for ${state.people} ${state.people===1?'person':'people'}, built around a ₹${state.budget.toLocaleString('en-IN')} budget.`;$('metricRow').innerHTML=[['₹'+Math.round(cost),'Estimated spend'],['₹'+Math.max(0,state.budget-Math.round(cost)),'Budget remaining'],[protein+' g','Avg. protein / meal'],[calories,'Avg. calories / meal']].map(x=>`<div class="metric"><strong>${x[0]}</strong><span>${x[1]}</span></div>`).join('');$('mealsPanel').innerHTML=`<div class="meal-grid">${meals.map((m,i)=>`<article class="meal-card"><span class="day">${m.day}</span><h3>${m.name}</h3><div class="meal-meta"><span>${m.time} min</span><span>${m.protein}g protein</span><span>₹${Math.round(m.cost*state.people/2)}</span></div><button data-swap="${i}">Swap meal ↻</button></article>`).join('')}</div>`;
 const all={};meals.forEach(m=>Object.entries(m.ingredients).forEach(([k,v])=>all[k]=v));const cats={Fresh:['Onion','Tomato','Capsicum','Coriander','Spinach','Mixed vegetables'],Protein:['Paneer','Curd','Tofu','Rajma','Chickpeas','Moong dal','Soya granules'],Pantry:[]};Object.keys(all).forEach(k=>{if(!cats.Fresh.includes(k)&&!cats.Protein.includes(k))cats.Pantry.push(k)});$('groceriesPanel').innerHTML=`<div class="grocery-grid">${Object.entries(cats).filter(([,v])=>v.length).map(([cat,items])=>`<section class="grocery-section"><h3>${cat}</h3>${items.filter(i=>all[i]).map(i=>`<label class="grocery-item"><input type="checkbox"><span>${i}</span><span>${all[i]}</span></label>`).join('')}</section>`).join('')}</div>`;
 document.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>toast('A fresh alternative is ready for your next plan'));}
$('continueButton').onclick=()=>{const error=validate();if(error)return toast(error);if(state.step<steps.length-1){state.step++;render()}else generate()};$('backButton').onclick=()=>{if(state.step){state.step--;render()}};$('newPlanButton').onclick=()=>{state.step=0;$('dashboard').classList.add('hidden');$('wizard').classList.remove('hidden');render()};$('brandButton').onclick=()=>{$('dashboard').classList.add('hidden');$('loadingScreen').classList.add('hidden');$('wizard').classList.remove('hidden');render()};$('printButton').onclick=()=>window.print();$('themeButton').onclick=()=>document.body.classList.toggle('dark');document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));t.classList.add('active');$('mealsPanel').classList.toggle('hidden',t.dataset.tab!=='meals');$('groceriesPanel').classList.toggle('hidden',t.dataset.tab!=='groceries')});render();
